#!/usr/bin/env bash
#
# Fail if an example's committed generator output no longer matches what the
# generators emit.
#
# Call this *after* building the example: its build.rs regenerates in place, so
# a dirty working tree afterwards means the committed files are stale. Pass the
# example's directory, e.g. `examples/notes-kb`.
#
# Checks the whole example tree rather than an allowlist of paths. An earlier
# version matched only paths containing "generated", which silently missed the
# DTO output — every example has `.dtos("src/schema/dto")`, and those files
# carry the "Generated by ontogen. DO NOT EDIT." header without the word in
# their path. Any future output directory would have been missed the same way,
# so the default is now "everything", with exclusions listed explicitly below.
#
# Lockfiles are the one exclusion. They are guarded instead by building with
# `--locked`, which fails loudly on a stale lock — a better signal than a diff,
# since cargo can touch a lockfile for reasons that have nothing to do with
# codegen.
set -euo pipefail

if [ $# -ne 1 ]; then
    echo "usage: $0 <example-dir>" >&2
    exit 2
fi

# Git pathspecs resolve against the cwd, so running this from anywhere but the
# repo root would silently look for `<cwd>/<example>` and find nothing — which
# used to report success. Anchor first.
cd "$(git rev-parse --show-toplevel)"

example="${1%/}"

# A renamed or misspelled example would otherwise match nothing and pass
# forever, which is the failure mode this guard exists to prevent.
if [ ! -d "$example" ]; then
    echo "::error title=Bad drift-check argument::no such directory: ${example}. The drift guard is pointed at a path that does not exist, so it is checking nothing." >&2
    exit 2
fi

# `git status --porcelain` rather than `git diff`, for two reasons: it reports
# untracked files, so a generator that starts emitting a *new* file is caught
# (git diff would have passed clean), and it does not need a `--exit-code`
# convention to interpret.
status=0
output=$(git status --porcelain -- "$example" ':(exclude)**/Cargo.lock') || status=$?

# Distinguish "git failed" from "there is drift". `git diff --quiet` exits 128
# on a git error — not a repo, a bad pathspec, a safe.directory refusal in a
# container — and treating that as drift tells the author to regenerate when
# the real problem is the environment.
if [ "$status" -ne 0 ]; then
    echo "::error title=Drift check could not run::git exited ${status} while inspecting ${example}. This is an environment problem, not stale output — do not regenerate on account of it." >&2
    exit "$status"
fi

if [ -z "$output" ]; then
    echo "✓ ${example}: committed generator output is current"
    exit 0
fi

# GitHub renders ::error:: as an annotation on the PR, so the reason shows up
# without opening the log.
echo "::error title=Stale generated output::${example} has committed generator output that no longer matches the generators. Run 'just regen-examples' and commit the result."

echo
echo "Changed, added or untracked under ${example}:"
echo "$output"
echo
echo "Diff (tracked files only; anything marked '??' above is a new file):"
git --no-pager diff -- "$example" ':(exclude)**/Cargo.lock'

exit 1
